{"summary": "实现 src/slugs.py 的 slugify：转小写、非字母数字段替换为单个 '-'、去首尾 '-'，保持签名与 docstring。", "findings": ["slugify 用 re.sub(r'[^a-z0-9]+','-',title.lower()).strip('-') 满足全部要求", "仅修改 src/slugs.py，未触碰 ranges.py 或 __init__.py"], "edits": [{"path": "src/slugs.py", "base_sha256": "28588d8f041cb8e5ee83e22ae6294b9ada8e6ae3bbfbe374a77587422ff97b34", "content": """"Slug helpers."""

import re


def slugify(title: str) -> str:
    """Convert a title into a URL-friendly slug.

    Lowercases the input, replaces each run of non-alphanumeric
    characters with a single hyphen, and strips leading/trailing hyphens.
    """
    return re.sub(r"[^a-z0-9]+", "-", title.lower()).strip("-")
